public function translateOpenOfficeAddress(string $openOfficeAddress): string
{
    $helper = $this->addressHelper;
    $delimiter = $helper->getPatternDelimiter();
    $dot = preg_quote($helper->getOdsSheetSeparator(), $delimiter);
    $dollar = preg_quote($helper->getAbsoluteMarker(), $delimiter);
    $colon = preg_quote($helper->getExcelRangeOperator(), $delimiter);
    $bang = $helper->getExcelSheetSeparator();
    $rangeOperator = $helper->getExcelRangeOperator();
    $flags = $this->patternModifiers;
    $notDot = '[^' . $dot . ']+';
    $notQuote = "[^']+";
    $sheetName = "(?:'{$notQuote}'|{$notDot})";

    $excelAddress = $openOfficeAddress;

    // Cell range 3-d reference
    // As we don't support 3-d ranges, we're just going to take a quick and dirty approach
    //  and assume that the second worksheet reference is the same as the first
    $excelAddress = (string) preg_replace(
        [
            $delimiter . $dollar . '?(' . $sheetName . ')' . $dot . '(' . $notDot . ')' . $colon . $dollar . '?(' . $sheetName . ')' . $dot . '(' . $notDot . ')' . $delimiter . $flags,
            $delimiter . $dollar . '?(' . $sheetName . ')' . $dot . '(' . $notDot . ')' . $colon . $dot . '(' . $notDot . ')' . $delimiter . $flags, // Cell range reference in another sheet
            $delimiter . $dollar . '?(' . $sheetName . ')' . $dot . '(' . $notDot . ')' . $delimiter . $flags, // Cell reference in another sheet
            $delimiter . $dot . '(' . $notDot . ')' . $colon . $dot . '(' . $notDot . ')' . $delimiter . $flags, // Cell range reference
            $delimiter . $dot . '(' . $notDot . ')' . $delimiter . $flags, // Simple cell reference
        ],
        [
            '$1' . $bang . '$2' . $rangeOperator . '$4',
            '$1' . $bang . '$2' . $rangeOperator . '$3',
            '$1' . $bang . '$2',
            '$1' . $rangeOperator . '$2',
            '$1',
        ],
        $excelAddress
    );

    return $excelAddress;
}

public static function convertToExcelAddressValue(string $openOfficeAddress): string
{
    return (new self())->translateOpenOfficeAddress($openOfficeAddress);
}

